"""Select word-reference heads with both reference voices and lexemes held out."""
from __future__ import annotations

import argparse
import hashlib
import json
import logging
from pathlib import Path

import numpy as np

from hindi_detector.artifacts import write_group
from hindi_detector.crossed_words import LABELS, PREFERRED, PRIORS, crossed_pairs, focus_log_loss, grouped_predictions, metrics
from hindi_detector.word_model import fit_word_head, load_bags

ROOT = Path(__file__).resolve().parents[1]
LOG = logging.getLogger(__name__)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--f5-evidence', type=Path, required=True)
    parser.add_argument('--pocket-evidence', type=Path, required=True)
    parser.add_argument('--plan', type=Path, required=True)
    parser.add_argument('--out', type=Path, required=True)
    args = parser.parse_args()
    if args.out.exists():
        raise FileExistsError('Use a new immutable crossed-word result group')
    plan = json.loads(args.plan.read_text())
    if plan['experiment_id'] != 'pocket_wordmatrix_v4' or set(plan['systems']) != {'pocket_hindi_parent', PREFERRED}:
        raise ValueError('Unexpected locked Pocket dataset')
    jobs = {j['id']: j for j in plan['jobs']}
    if len(jobs) != 512:
        raise ValueError('Unexpected matrix shape')
    dirs = [args.f5_evidence, args.pocket_evidence]
    inputs = {}
    for directory, expected_count in zip(dirs, [512, 1024], strict=True):
        m = json.loads((directory / 'manifest.json').read_text())
        if m['failures'] or m['successes'] != expected_count or len(m['items']) != expected_count:
            raise ValueError('Investigate failed evidence before fitting a complete crossed matrix')
        inputs[str(directory)] = hashlib.sha256((directory / 'manifest.json').read_bytes()).hexdigest()
    sources = []
    for p in [Path(__file__), ROOT / 'hindi_detector/crossed_words.py', ROOT / 'hindi_detector/reference_words.py', ROOT / 'hindi_detector/word_model.py']:
        sources.append({'path': str(p.relative_to(ROOT)), 'sha256': hashlib.sha256(p.read_bytes()).hexdigest(), 'source_utf8': p.read_text()})
    sets = {split: {'voices': {j['speaker_id'] for j in jobs.values() if j['split'] == split},
                    'words': {j['focus_word'] for j in jobs.values() if j['split'] == split}}
            for split in ['train', 'development', 'reserved_evaluation']}
    for i, left in enumerate(sets):
        for right in list(sets)[i + 1:]:
            if sets[left]['voices'] & sets[right]['voices'] or sets[left]['words'] & sets[right]['words']:
                raise ValueError('Crossed held-out voice/focus-word leakage')
    train, dev = [], []
    for directory in dirs:
        selected, _ = load_bags(directory, splits={'train', 'development'})
        train += [b for b in selected if b['split'] == 'train']
        dev += [b for b in selected if b['split'] == 'development']
    for split, bags in [('train', train), ('development', dev)]:
        expected_jobs = {j['id'] for j in jobs.values() if j['split'] == split}
        if len(bags) != 3 * len(expected_jobs) or {b['sentence_id'] for b in bags} != expected_jobs:
            raise ValueError('Incomplete source coverage for split ' + split)
    speakers = sorted(sets['train']['voices'], key=lambda s: hashlib.sha256(('pocket-cross-v4:voice:' + s).encode()).hexdigest())
    words = sorted(sets['train']['words'], key=lambda s: hashlib.sha256(('pocket-cross-v4:word:' + s).encode()).hexdigest())
    if len(speakers) != 8 or len(words) != 8:
        raise ValueError('Expected eight training voice groups and focal lexemes')
    voice_fold = {s: i % 3 for i, s in enumerate(speakers)}
    word_fold = {w: i % 3 for i, w in enumerate(words)}
    folds = []
    for fold in range(3):
        fitting = [b for b in train if voice_fold[b['speaker_id']] != fold and word_fold[jobs[b['sentence_id']]['focus_word']] != fold]
        validating = [b for b in train if voice_fold[b['speaker_id']] == fold and word_fold[jobs[b['sentence_id']]['focus_word']] == fold]
        a, b = crossed_pairs(fitting, jobs), crossed_pairs(validating, jobs)
        train_voices = {p[k] for p in a for k in ['speaker_id', 'reference_speaker_id']}
        val_voices = {p[k] for p in b for k in ['speaker_id', 'reference_speaker_id']}
        if train_voices & val_voices or {p['focus_word'] for p in a} & {p['focus_word'] for p in b}:
            raise ValueError('CV query/reference/focal-word leakage')
        folds.append((a, b))
    full = crossed_pairs(train, jobs); development = crossed_pairs(dev, jobs)
    models, selection, report = {}, {}, {}
    for branch in ['phonetics', 'prosody', 'combined']:
        candidates = []
        for l2 in [.01, .1, 1.]:
            losses = []
            for fitting, validating in folds:
                model = fit_word_head(fitting, branch, l2, source_priors=PRIORS)
                losses.append(focus_log_loss(model, validating))
            candidate = {'l2': l2, 'focus_fold_log_losses': losses, 'mean_focus_cv_log_loss': float(np.mean(losses))}
            candidates.append(candidate); LOG.info('%s L2 %s focal CV %.5f', branch, l2, candidate['mean_focus_cv_log_loss'])
        chosen = min(candidates, key=lambda row: row['mean_focus_cv_log_loss'])
        model = fit_word_head(full, branch, chosen['l2'], source_priors=PRIORS)
        model.update(reference_recipe='signed_and_absolute_query_minus_preferred_word_v1', preferred_source=PREFERRED,
                     status='weak_crossed_word_source_evidence_not_validated_hindi_accuracy',
                     label_source='user_preferred_nepali_checkpoint_and_hindi_source_roles_not_word_gold',
                     phone_encoder_revision=json.loads((args.f5_evidence / 'manifest.json').read_text())['phone_encoder_revision'])
        models[branch] = model; selection[branch] = {'selected': chosen, 'candidates': candidates}
        report[branch] = {'development': metrics(grouped_predictions(model, development))}
    # Reading test acoustics happens only after all branch/regularization choices are fixed.
    test_bags = []
    for directory in dirs:
        selected, _ = load_bags(directory, splits={'reserved_evaluation'})
        test_bags += selected
    test = crossed_pairs(test_bags, jobs)
    predictions = {}
    for branch, model in models.items():
        predictions[branch] = grouped_predictions(model, test)
        report[branch]['held_out_voice_and_focus_word'] = metrics(predictions[branch])
    summary = {'status': 'three_crossed_reference_heads_trained', 'branches': report,
               'train_queries': len(train), 'development_queries': len(dev), 'test_queries': len(test_bags),
               'train_pairs': len(full), 'test_pairs': len(test), 'source_labels': LABELS, 'source_priors': PRIORS,
               'cv_policy': 'Split both voice groups and focal lexemes, including reference voices; choose by focal-word weak source log loss.',
               'human_word_gold_used': 0, 'validated_word_hindi_accuracy': None, 'reliable_automatic_detector': False,
               'limits': ['Focal scores are weak checkpoint/source evidence, not proof a word is a Hindi pronunciation error.',
                          'Positive utterance bags never label every word as erroneous. Focal model selection is still weakly supervised.',
                          'Pocket parent versus Nepali changes checkpoint within one architecture; exact historical initialization hash is unverified.',
                          'The F5 matrix has already been inspected; predefined voice/lexeme splits do not make it pristine untouched evaluation.',
                          'Native-speech false alarms and verified localized/prosody errors remain necessary reliability checks.',
                          'Underlying phonetic probe and G2P candidate limitations remain; no performance claim for Nepal Bhasa/Newa.']}
    write_group(args.out, {'models.json': models, 'report.json': summary, 'selection.json': selection,
                          'test_predictions.json': predictions, 'source_snapshot.json': sources,
                          'folds.json': {'voice_folds': voice_fold, 'word_folds': word_fold}},
                'Train word-focused preferred-reading comparisons across different voices with same-architecture checkpoint controls.',
                ['Plan SHA ' + hashlib.sha256(args.plan.read_bytes()).hexdigest(),
                 'Input evidence manifest hashes ' + json.dumps(inputs),
                 'python -m scripts.train_crossed_words --f5-evidence reports/wordlab_matrix_f5_v3 --pocket-evidence reports/wordlab_pocket_matrix_v4 --plan data/pocket_wordmatrix_v4/plan.json --out NEW'])
    print(json.dumps(summary))


if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    try:
        main()
    except Exception:
        LOG.exception('Crossed focal-word training failed; no substitute labels or scores')
        raise

"""Preferred-word comparisons whose query and reference voice groups differ."""
from __future__ import annotations

from collections import defaultdict

import numpy as np

from hindi_detector.evaluation import binary_metrics
from hindi_detector.reference_words import pair_words
from hindi_detector.word_model import predict_bag

PREFERRED = 'pocket_nepali_v1c'
LABELS = {'indicf5_stock': 1, 'pocket_hindi_parent': 1, PREFERRED: 0}
PRIORS = {'indicf5_stock': .25, 'pocket_hindi_parent': .25, PREFERRED: .5}


def crossed_pairs(bags: list[dict], jobs: dict[str, dict]) -> list[dict]:
    cells = defaultdict(dict)
    prompts = defaultdict(list)
    for original in bags:
        job = jobs[original['sentence_id']]
        if original['system'] not in LABELS or any(original[k] != job[k] for k in ['speaker_id', 'split']):
            raise ValueError('Crossed source/job metadata mismatch')
        bag = original | {'class_id': LABELS[original['system']]}
        if bag['system'] in cells[job['id']]:
            raise ValueError('Duplicate TTS source in a crossed cell')
        cells[job['id']][bag['system']] = bag
    for job_id, sources in cells.items():
        if set(sources) != set(LABELS):
            raise ValueError('Every crossed cell needs all three actual source readings')
        job = jobs[job_id]
        prompts[(job['split'], job['prompt_id'])].append((job, sources))
    if not prompts:
        raise ValueError('No crossed prompts')
    pairs = []
    for group in prompts.values():
        group.sort(key=lambda row: row[0]['speaker_id'])
        speakers = [j['speaker_id'] for j, _ in group]
        if len(set(speakers)) != len(speakers) or len(speakers) < 2:
            raise ValueError('Need at least two distinct reference source groups per prompt')
        for index, (job, sources) in enumerate(group):
            for offset in range(1, min(2, len(group) - 1) + 1):
                other_job, other = group[(index + offset) % len(group)]
                if job['focus_word'] != other_job['focus_word']:
                    raise ValueError('Reference focus word mismatch')
                reference = other[PREFERRED]
                for query in sources.values():
                    if query['speaker_id'] == reference['speaker_id']:
                        raise ValueError('Same-voice reference would weaken the nuisance control')
                    pair = pair_words(query, reference)
                    indices = [i for i, w in enumerate(pair['words']) if w['word'] == job['focus_word']]
                    if len(indices) != 1:
                        raise ValueError('Focus word must occur exactly once in the actual aligned sequence')
                    pair.update(focus_word=job['focus_word'], focus_index=indices[0], prompt_id=job['prompt_id'])
                    pairs.append(pair)
    return pairs


def grouped_predictions(model: dict, pairs: list[dict]) -> list[dict]:
    groups = defaultdict(list)
    for pair in pairs:
        bag, words = predict_bag(model, pair)
        groups[pair['query_clip_id']].append((pair, bag, words))
    output = []
    for identifier, rows in groups.items():
        p = rows[0][0]
        focus = [words[p['focus_index']] for _, _, words in rows]
        score = float(np.mean(focus)) if all(v is not None for v in focus) else None
        output.append({k: p[k] for k in ['system', 'class_id', 'speaker_id', 'sentence_id', 'split', 'focus_word', 'focus_index']} |
                      {'query_clip_id': identifier, 'reference_clip_ids': [row[0]['reference_clip_id'] for row in rows],
                       'reference_speaker_ids': [row[0]['reference_speaker_id'] for row in rows],
                       'bag_source_evidence': float(np.mean([row[1] for row in rows])), 'focus_source_evidence': score,
                       'words': [{'word': word['word'], 'start': word['start'], 'end': word['end'],
                                  'source_evidence': float(np.mean([r[2][i] for r in rows])) if all(r[2][i] is not None for r in rows) else None}
                                 for i, word in enumerate(p['words'])]})
    return output


def focus_log_loss(model: dict, pairs: list[dict]) -> float:
    rows = grouped_predictions(model, pairs)
    if any(row['focus_source_evidence'] is None for row in rows):
        raise ValueError('Focus CV coverage incomplete; never fill missing phones with low risk')
    loss = 0.
    for system, prior in PRIORS.items():
        group = [r for r in rows if r['system'] == system]
        if not group:
            raise ValueError('Focus CV missing a source')
        p = np.clip([r['focus_source_evidence'] for r in group], 1e-8, 1 - 1e-8)
        y = LABELS[system]
        loss += prior * float(np.mean(-(y * np.log(p) + (1 - y) * np.log1p(-p))))
    return loss


def metrics(rows: list[dict]) -> dict:
    result = {'queries': len(rows), 'focus_score_meaning': 'Weak source evidence on the held-out focal word, not certified pronunciation correctness'}
    for name, systems in [('pocket_same_architecture', {PREFERRED, 'pocket_hindi_parent'}),
                          ('indicf5_vs_pocket', {PREFERRED, 'indicf5_stock'})]:
        members = [r for r in rows if r['system'] in systems]
        valid = [r for r in members if r['focus_source_evidence'] is not None]
        if {r['system'] for r in valid} != systems:
            raise ValueError('Cannot report both-source focus metrics without coverage')
        result[name] = {'n': len(members), 'focus_coverage': len(valid) / len(members),
                        'focus_source_metrics': binary_metrics(np.array([r['class_id'] for r in valid]), np.array([r['focus_source_evidence'] for r in valid])),
                        'whole_bag_source_metrics': binary_metrics(np.array([r['class_id'] for r in members]), np.array([r['bag_source_evidence'] for r in members]))}
    return result

"""Compare aligned words with a preferred reading of the same text."""
from __future__ import annotations

from collections import defaultdict

import numpy as np

from hindi_detector.word_model import LABELS, predict_bag

RECIPE = 'signed_and_absolute_query_minus_preferred_word_v1'
PREFERRED = {'native_recording', 'audio8_r3'}


def pair_words(query: dict, reference: dict) -> dict:
    if query['clip_id'] == reference['clip_id'] or query['audio_sha256'] == reference['audio_sha256']:
        raise ValueError('Self-reference would make negative pairs artificially easy')
    if query['split'] != reference['split']:
        raise ValueError('Reference and query must remain in the same split')
    if [w['word'] for w in query['words']] != [w['word'] for w in reference['words']]:
        raise ValueError('Reference must read exactly the same word sequence')
    result = {k: query[k] for k in ['words', 'speaker_id', 'sentence_id', 'split', 'system', 'class_id']}
    result.update(clip_id=query['clip_id'] + '__vs__' + reference['clip_id'],
                  query_clip_id=query['clip_id'], reference_clip_id=reference['clip_id'],
                  query_audio_sha256=query['audio_sha256'], reference_audio_sha256=reference['audio_sha256'],
                  reference_speaker_id=reference['speaker_id'], reference_system=reference['system'], recipe=RECIPE)
    for key in ['phonetics', 'prosody']:
        left, right = np.asarray(query[key]), np.asarray(reference[key])
        if left.shape != right.shape or left.ndim != 2 or not np.isfinite(left).all() or not np.isfinite(right).all():
            raise ValueError('Reference word feature dimensions/values disagree')
        delta = left - right
        result[key] = np.concatenate([delta, np.abs(delta)], axis=1)
    result['phone_mask'] = query['phone_mask'] & reference['phone_mask']
    return result


def preferred_pairs(bags: list[dict]) -> list[dict]:
    """Two positive comparisons and two non-self negative comparisons per text."""
    groups = defaultdict(dict)
    for bag in bags:
        if bag['system'] not in LABELS:
            continue
        group = groups[(bag['sentence_id'], bag['speaker_id'], bag['split'])]
        if bag['system'] in group:
            raise ValueError('Duplicate source reading for a text/reference group')
        group[bag['system']] = bag
    if not groups:
        raise ValueError('No matched reference groups')
    result = []
    for group in groups.values():
        if set(group) != set(LABELS):
            raise ValueError('Need matched F5, Audio8 R3 and native words; never fabricate a missing reference')
        for query, reference in [('indicf5_stock', 'native_recording'), ('indicf5_stock', 'audio8_r3'),
                                 ('native_recording', 'audio8_r3'), ('audio8_r3', 'native_recording')]:
            result.append(pair_words(group[query], group[reference]))
    return result


def predict_reference(model: dict, query: dict, reference: dict) -> tuple[float, list[float | None]]:
    if model.get('reference_recipe') != RECIPE or reference['system'] not in PREFERRED:
        raise ValueError('Unsupported reference recipe or unapproved reference source')
    return predict_bag(model, pair_words(query, reference))

"""Weakly supervised word evidence; no per-word Hindi gold is fabricated."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

import numpy as np

LABELS = {'indicf5_stock': 1, 'audio8_r3': 0, 'native_recording': 0}
PRIORS = {'indicf5_stock': .5, 'audio8_r3': .25, 'native_recording': .25}


def load_bags(directory: Path, *, splits: set[str] | None = None) -> tuple[list[dict], dict]:
    manifest = json.loads((directory / 'manifest.json').read_text())
    bags = []
    for row in manifest['items']:
        if row['status'] != 'ok_unreviewed_word_evidence':
            continue
        if splits is not None and row['split'] not in splits:
            continue
        detail, feature = directory / row['detail'], directory / row['features']
        if any(not p.resolve().is_relative_to(directory.resolve()) for p in [detail, feature]):
            raise ValueError('Evidence paths outside group')
        if hashlib.sha256(detail.read_bytes()).hexdigest() != row['detail_sha256'] or hashlib.sha256(feature.read_bytes()).hexdigest() != row['feature_sha256']:
            raise ValueError('Word evidence checksum mismatch')
        data = json.loads(detail.read_text())
        with np.load(feature, allow_pickle=False) as stored:
            if stored['parent_audio_sha256'].item() != row['audio_sha256']:
                raise ValueError('Word features/audio identity mismatch')
            phonetics, prosody = stored['phonetics'].copy(), stored['prosody'].copy()
        n = len(data['words'])
        if phonetics.shape != (n, 2 * len(manifest['phone_vocabulary'])) or prosody.shape != (n, len(manifest['prosody_feature_names'])):
            raise ValueError('Word feature schema mismatch')
        if not np.isfinite(phonetics).all() or not np.isfinite(prosody).all():
            raise ValueError('Nonfinite word features')
        system = {'audio8_dpo_R3': 'audio8_r3'}.get(row['system'], row['system'])
        bags.append({'clip_id': row['clip_id'], 'audio_sha256': row['audio_sha256'],
                     'sentence_id': row['sentence_id'], 'speaker_id': row['speaker_id'], 'split': row['split'],
                     'system': system, 'class_id': LABELS.get(system), 'words': data['words'],
                     'phonetics': phonetics, 'prosody': prosody,
                     'phone_mask': np.array([w['phone_evidence_available'] for w in data['words']], dtype=bool)})
    return bags, manifest


def bag_weights(bags: list[dict], priors: dict[str, float] | None = None) -> np.ndarray:
    priors = PRIORS if priors is None else priors
    systems = [b['system'] for b in bags]
    if set(systems) != set(priors) or not priors or any(not np.isfinite(v) or v <= 0 for v in priors.values()) or not np.isclose(sum(priors.values()), 1.):
        raise ValueError('Need every declared source and finite positive priors summing to one')
    return np.array([priors[s] / systems.count(s) for s in systems], dtype=np.float32)


def vectors(bag: dict, branch: str) -> tuple[np.ndarray, np.ndarray]:
    if branch == 'prosody':
        return bag['prosody'], np.ones(len(bag['words']), dtype=bool)
    if branch == 'phonetics':
        return bag['phonetics'], bag['phone_mask']
    if branch == 'combined':
        return np.concatenate([bag['phonetics'], bag['prosody']], axis=1), bag['phone_mask']
    raise ValueError('Unknown word branch')


def pool_logits(logits: np.ndarray) -> float:
    logits = np.asarray(logits, dtype=float)
    if logits.ndim != 1 or not len(logits) or not np.isfinite(logits).all():
        raise ValueError('Need finite nonempty word logits')
    maximum = float(logits.max())
    return maximum + float(np.log(np.exp(logits - maximum).mean()))


def predict_bag(model: dict, bag: dict) -> tuple[float, list[float | None]]:
    values, valid = vectors(bag, model['branch'])
    if not valid.any():
        raise ValueError('No usable words; cannot infer a native/Hindi bag class')
    mean, scale, weight = (np.asarray(model[k]) for k in ['feature_mean', 'feature_scale', 'weight'])
    if values.shape[1] != len(weight) or mean.shape != weight.shape or scale.shape != weight.shape or (scale <= 0).any():
        raise ValueError('Word model/feature recipe mismatch')
    if not all(np.isfinite(a).all() for a in [values, mean, scale, weight]) or not np.isfinite(model['bias']):
        raise ValueError('Nonfinite word model/input')
    logits = ((values[valid] - mean) / scale) @ weight + model['bias']
    probabilities = np.exp(-np.logaddexp(0, -logits))
    scores = [None] * len(values)
    for index, probability in zip(np.flatnonzero(valid), probabilities, strict=True):
        scores[int(index)] = float(probability)
    pooled = pool_logits(logits)
    return float(np.exp(-np.logaddexp(0, -pooled))), scores


def fit_word_head(bags: list[dict], branch: str, l2: float, *, source_priors: dict[str, float] | None = None) -> dict:
    import torch

    torch.set_num_threads(2)
    torch.manual_seed(0)
    raw, masks = zip(*(vectors(b, branch) for b in bags))
    if any(not m.any() for m in masks):
        raise ValueError('Training contains an unusable word bag')
    weights = bag_weights(bags, source_priors)
    if any(b['class_id'] not in {0, 1} for b in bags):
        raise ValueError('Training requires explicit weak source labels')
    # Equal source/utterance weight: long utterances do not dominate scaling.
    mean = sum(float(w) * x[m].mean(0) for w, x, m in zip(weights, raw, masks, strict=True))
    variance = sum(float(w) * ((x[m] - mean) ** 2).mean(0) for w, x, m in zip(weights, raw, masks, strict=True))
    scale = np.maximum(np.sqrt(variance), max(float(np.median(np.sqrt(variance))) * .1, 1e-4))
    max_words, dimension = max(int(m.sum()) for m in masks), len(mean)
    z, mask = np.zeros((len(bags), max_words, dimension), dtype=np.float32), np.zeros((len(bags), max_words), dtype=bool)
    for i, (x, m) in enumerate(zip(raw, masks, strict=True)):
        n = int(m.sum()); z[i, :n] = (x[m] - mean) / scale; mask[i, :n] = True
    z = torch.tensor(z); mask = torch.tensor(mask)
    y = torch.tensor([b['class_id'] for b in bags], dtype=torch.float32)
    mass = torch.tensor(weights)
    coefficient = torch.nn.Parameter(torch.zeros(dimension)); bias = torch.nn.Parameter(torch.zeros(()))
    optimizer = torch.optim.Adam([coefficient, bias], lr=.01)
    final_loss = None
    for _ in range(400):
        optimizer.zero_grad(set_to_none=True)
        local = z @ coefficient + bias
        bag_logits = torch.logsumexp(local.masked_fill(~mask, -float('inf')), dim=1) - torch.log(mask.sum(1).float())
        bag_loss = torch.nn.functional.binary_cross_entropy_with_logits(bag_logits, y, reduction='none')
        negative_word_loss = (torch.nn.functional.softplus(local) * mask).sum(1) / mask.sum(1)
        loss = (mass * (bag_loss + .25 * (1 - y) * negative_word_loss)).sum() + l2 / 2 * coefficient.square().sum()
        if not torch.isfinite(loss):
            raise ValueError('Nonfinite weak-word training loss')
        loss.backward(); optimizer.step(); final_loss = float(loss.detach())
    if not torch.isfinite(coefficient).all() or not torch.isfinite(bias):
        raise ValueError('Nonfinite fitted word head')
    return {'branch': branch, 'weight': coefficient.detach().numpy().tolist(), 'bias': float(bias.detach()),
            'feature_mean': mean.tolist(), 'feature_scale': scale.tolist(), 'l2': l2,
            'steps': 400, 'seed': 0, 'training_loss': final_loss,
            'source_priors': PRIORS if source_priors is None else source_priors,
            'pooling': 'log-mean-exp of word logits, temperature 1',
            'word_score_meaning': 'Weak evidence for the positive source bag; not a calibrated Hindi word label'}
